/**
 * Retrieve an authorization code
 *
 * Retrieves the authorization of the Qonto user i.e. an authorization code that you will be able to exchange for a [set of tokens](/api-reference/business-api/authentication/oauth2/create_tokens).
 *
 * 1. Your app should include a "Connect with Qonto" button which should trigger this endpoint;
 * <Warning>
 * If you are triggering this endpoint on the Sandbox environment (https://oauth-sandbox.staging.qonto.co), please make sure to be logged in on the [Sandbox web-app](https://sandbox.staging.qonto.co/devportal) first through your [Developer Portal](https://developers.qonto.com/) account.
 * </Warning>
 * <Info>
 * If you just want to connect your app to one single organization, you can just send the endpoint URL to the Qonto user from whom you need to get the consent.
 * </Info>
 * 2. After clicking on your button, the Qonto user will be redirected to Qonto and will have to authenticate;
 * 3. (optional) The Qonto will have to select an organization;
 * 3. The Qonto user will have to give their consent to your app for the organization they have just selected (or for the organization identified by the `organization_id` or the `registration_id` query parameter);
 * 4. The Qonto user will be automatically redirected back to your `redirect_uri`.
 */
export const getOauth2Auth = <ThrowOnError extends boolean = false>(options: Options<GetOauth2AuthData, ThrowOnError>): RequestResult<unknown, GetOauth2AuthErrors, ThrowOnError> => (options.client ?? client).get<unknown, GetOauth2AuthErrors, ThrowOnError>({ url: '/oauth2/auth', ...options });

/**
 * Create or refresh tokens
 *
 * <Warning>This call must be performed on your backend as you should never expose your client secret.</Warning>
 *
 * Creates or refreshes a set of tokens for the authenticated membership.
 *
 * This set of tokens contains:
 * - always: an access token (you will need this token to authenticate yourself to any other endpoint);
 * - if you used the `offline_access` scope when [retrieving an authorization code](/api-reference/business-api/authentication/oauth2/retrieve_authorization): a refresh token;
 * - if you used the `openid` scope when [retrieving an authorization code](/api-reference/business-api/authentication/oauth2/retrieve_authorization): an ID token.
 *
 * The access token and the ID token are valid for **1 hour**,  the refresh token for **90 days**.  Once the access token has reached its expiration date, you won’t be able to access the Business API with it anymore.
 *
 * <AccordionGroup>
 *
 * <Accordion title="If you create a set of tokens for the first time">
 * Use the authorization `code` you've received at [the previous step](/api-reference/business-api/authentication/oauth2/retrieve_authorization).
 * </Accordion>
 *
 * <Accordion title="If you want to refresh an existing access token">
 * Use the last refresh token you've received.
 * <Warning>Don’t forget to store your new refresh token as the previous one will be invalidated 👉 you will need it for the next refresh.</Warning>
 * Always opt for a **proactive** refresh vs a reactive refresh to avoid reaching the [rate limitations](/get-started/general/rate-limitations), i.e. check if your access token is expired and refresh it if needed before making any API call instead of refreshing it after getting a `401` error.
 * </Accordion>
 *
 * </AccordionGroup>
 */
export const postOauth2Token = <ThrowOnError extends boolean = false>(options: Options<PostOauth2TokenData, ThrowOnError>): RequestResult<PostOauth2TokenResponses, PostOauth2TokenErrors, ThrowOnError> => (options.client ?? client).post<PostOauth2TokenResponses, PostOauth2TokenErrors, ThrowOnError>({
    ...urlSearchParamsBodySerializer,
    url: '/oauth2/token',
    ...options,
    headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        ...options.headers
    }
});

